mkdir -p /tmp/work && cat > /tmp/work/run.py <<'E'
import json,time,urllib.request,urllib.error,datetime,sys
B="http://localhost:8080"; tok=[None]; log=[]
def req(path,method="GET"):
    for i in range(200):
        h={}
        if path!="/token":
            if not tok[0]: tok[0]=req("/token","POST")["token"]
            h["Authorization"]="Bearer "+tok[0]
        try:
            r=urllib.request.urlopen(urllib.request.Request(B+path,method=method,headers=h,data=b"" if method=="POST" else None),timeout=30)
            return json.load(r)
        except urllib.error.HTTPError as e:
            body=e.read().decode(errors="replace")
            if e.code==404: return None
            log.append((path,e.code,body[:120],e.headers.get("Retry-After")))
            if e.code==401: tok[0]=None; continue
            ra=e.headers.get("Retry-After")
            try: w=float(ra)
            except: 
                try: w=float(json.loads(body).get("retry_after"))
                except: w=1
            time.sleep(w+0.1)
        except Exception as e:
            log.append((path,str(e))); time.sleep(1)
    raise SystemExit("fail "+path)
orders={};dups=0;p=1
while p:
    d=req(f"/orders?page={p}")
    for o in d["items"]:
        if o["id"] in orders:
            dups+=1
            if orders[o["id"]]!=o: print("DIFF",o,orders[o["id"]])
        else: orders[o["id"]]=o
    p=int(d["next"].split("=")[1]) if d["next"] else 0
print(len(orders),dups,d["total_pages"])
lo=datetime.datetime(2025,3,1,tzinfo=datetime.timezone.utc);hi=datetime.datetime(2025,6,1,tzinfo=datetime.timezone.utc)
cust={};reg={"north":0,"south":0,"east":0,"west":0};n=0;tot=0
for o in orders.values():
    if o["status"]!="shipped": continue
    t=datetime.datetime.fromisoformat(o["placed_at"].replace("Z","+00:00"))
    if t.tzinfo is None: print("naive",o)
    if not(lo<=t<hi): continue
    c=o["customer_id"]
    if c not in cust: cust[c]=req("/customers/"+c)
    if cust[c] is None: print("missing cust",o); continue
    v=(o["amount_cents"]*(100-cust[c]["discount_pct"])+50)//100
    reg[cust[c]["region"]]+=v;tot+=v;n+=1
print(set(o["status"] for o in orders.values()))
print(log[:5],len(log))
json.dump({"total_cents":tot,"order_count":n,"duplicates_skipped":dups,"by_region":reg},open("/workspace/result.json","w"),indent=2)
print(tot,n,reg)
E
